  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "开场：树是计算机科学中最基础的非线性结构，从文件系统到数据库索引无处不在。今天我们从现实类比出发，建立树的直觉。",
      "blocks": [
        {"id": "b_cover", "type": "hero", "intent": "封面：标题+一句副题，点明树是层次化数据组织的基础。"}
      ]
    },
    {
      "id": "why-tree",
      "kind": "content",
      "headline": "为什么需要树？",
      "lead": "线性结构（数组、链表）无法高效表达层次关系与快速查找。",
      "notes": "举例：文件系统是典型的树——根目录下分文件夹，再分文件。如果只用列表，查找一个文件需要遍历所有条目。树结构让搜索路径清晰，平均查找时间从 O(n) 降到 O(log n)。",
      "blocks": [
        {"id": "b_why1", "type": "list", "intent": "对比线性结构与树结构在组织层次数据时的差异。"}
      ]
    },
    {
      "id": "terminology",
      "kind": "content",
      "eyebrow": "基本概念",
      "headline": "树的术语",
      "lead": "根、父、子、兄弟、叶子、深度、高度——一套精确的家族比喻。",
      "notes": "根节点是唯一没有父节点的节点。叶子节点没有子节点。深度是从根到该节点的边数，高度是从该节点到最远叶子的边数。例如：一个只有根节点的树，深度为 0，高度为 0。",
      "blocks": [
        {"id": "b_term1", "type": "agenda", "intent": "列出并解释树的核心术语，每个术语配一个简单例子。"}
      ]
    },
    {
      "id": "binary-tree",
      "kind": "content",
      "eyebrow": "二叉树",
      "headline": "二叉树：每个节点最多两个分支",
      "lead": "左子树和右子树，是树家族中最常用的变体。",
      "notes": "二叉树限制每个节点最多两个子节点，简化了实现。满二叉树：所有叶子在同一层，且非叶子节点都有两个子节点。完全二叉树：除了最后一层，其他层都满，最后一层节点靠左排列。",
      "blocks": [
        {"id": "b_bt1", "type": "list", "intent": "定义二叉树，并区分满二叉树与完全二叉树。"}
      ]
    },
    {
      "id": "traversal-intro",
      "kind": "content",
      "headline": "遍历：如何访问所有节点？",
      "lead": "前序、中序、后序——三种递归顺序，对应不同的应用场景。",
      "notes": "前序：根→左→右（用于复制树）。中序：左→根→右（用于二叉搜索树得到有序序列）。后序：左→右→根（用于删除树）。举例：一棵树根为 A，左子 B，右子 C，前序输出 A B C，中序 B A C，后序 B C A。",
      "blocks": [
        {"id": "b_trav1", "type": "agenda", "intent": "用具体例子展示三种遍历顺序及其输出。"}
      ]
    },
    {
      "id": "traversal-example",
      "kind": "content",
      "headline": "遍历实例：一棵小树",
      "lead": "用一棵具体的三节点树，手动走一遍三种遍历。",
      "notes": "树结构：根节点 10，左子 5，右子 15。前序：10→5→15。中序：5→10→15。后序：5→15→10。注意中序输出是升序，这正是二叉搜索树的性质。",
      "blocks": [
        {"id": "b_trav2", "type": "flow", "intent": "用流程图展示三种遍历的递归步骤。"}
      ]
    },
    {
      "id": "bst-intro",
      "kind": "content",
      "eyebrow": "二叉搜索树",
      "headline": "二叉搜索树（BST）：有序的二叉树",
      "lead": "左小右大，查找效率 O(log n)。",
      "notes": "BST 性质：对于任意节点，左子树所有值小于它，右子树所有值大于它。查找时，每次比较缩小一半范围。最坏情况（退化为链表）为 O(n)，所以需要平衡。",
      "blocks": [
        {"id": "b_bst1", "type": "callout", "intent": "强调 BST 的查找原理和效率。"}
      ]
    },
    {
      "id": "bst-search",
      "kind": "content",
      "headline": "BST 查找：一步步缩小范围",
      "lead": "从根开始，比目标大则向右，小则向左。",
      "notes": "举例：在 BST [10, 5, 15, 3, 7, 12, 18] 中查找 7。从根 10 开始，7<10 向左到 5，7>5 向右到 7，找到。共 3 步，而线性查找需要 4 步。",
      "blocks": [
        {"id": "b_bst2", "type": "flow", "intent": "用流程图演示 BST 查找 7 的过程。"}
      ]
    },
    {
      "id": "bst-insert",
      "kind": "content",
      "headline": "BST 插入：保持有序",
      "lead": "插入新节点时，始终遵循左小右大规则。",
      "notes": "插入 8 到上述树：从根 10 开始，8<10 向左到 5，8>5 向右到 7，8>7 向右，7 无右子，插入为 7 的右子。插入后树仍为 BST。",
      "blocks": [
        {"id": "b_bst3", "type": "flow", "intent": "演示 BST 插入 8 的步骤。"}
      ]
    },
    {
      "id": "bst-delete",
      "kind": "content",
      "headline": "BST 删除：三种情况",
      "lead": "删除叶子、删除单子节点、删除双子节点——后者最复杂。",
      "notes": "删除叶子直接移除。删除单子节点：用子节点替换。删除双子节点：找到右子树的最小节点（或左子树的最大节点）替换，然后删除那个节点。举例：删除根 10，用右子树最小 12 替换。",
      "blocks": [
        {"id": "b_bst4", "type": "agenda", "intent": "列出 BST 删除的三种情况并各给一个例子。"}
      ]
    },
    {
      "id": "balance-issue",
      "kind": "content",
      "headline": "平衡问题：当 BST 退化为链表",
      "lead": "如果插入有序数据，BST 变成一条直线，查找退化为 O(n)。",
      "notes": "例如依次插入 1,2,3,4,5，树变成右斜链。查找 5 需要 5 步。解决方案：平衡二叉树（如 AVL、红黑树）通过旋转保持高度差 ≤1。",
      "blocks": [
        {"id": "b_bal1", "type": "compare", "intent": "对比平衡 BST 与退化链表的查找效率。"}
      ]
    },
    {
      "id": "tree-applications",
      "kind": "content",
      "eyebrow": "应用",
      "headline": "树无处不在",
      "lead": "文件系统、数据库索引、编译器语法树、网络路由。",
      "notes": "文件系统是树（根目录→子目录→文件）。数据库 B+ 树索引让千万级数据查找只需几次 I/O。编译器用抽象语法树（AST）表示代码结构。路由协议用树组织网络拓扑。",
      "blocks": [
        {"id": "b_app1", "type": "list", "intent": "列举树在现实系统中的应用实例。"}
      ]
    },
    {
      "id": "quiz",
      "kind": "quiz",
      "headline": "随堂检验",
      "notes": "考察对树基本概念和 BST 性质的理解。",
      "blocks": [
        {"id": "bq", "type": "quiz", "intent": "考察树的术语和 BST 查找效率。"}
      ]
    },
    {
      "id": "summary",
      "kind": "hero",
      "notes": "收尾：树是层次化数据的自然模型，二叉树和 BST 是核心工具。理解遍历和平衡是进阶的基础。",
      "blocks": [
        {"id": "b_summary", "type": "hero", "intent": "收尾：总结树的核心概念和重要性。"}
      ]
    }
  ]
